------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260728_opportunities.sql
------------------------------------------------------------------------
-- Exclusive, member-only opportunities.
--
-- The existing /api/opportunities route is a public, unauthenticated proxy over
-- an external feed. This table is the admin-managed store that sits alongside
-- it and adds the thing awardees actually pay for: listings outsiders cannot
-- see. Visibility tiering is enforced server-side by visibleTiersFor() in
-- lib/opportunities/server.ts; the RLS policies below are defence in depth.
--
-- Prerequisite: supabase/SETUP-MEMBER-HUB.sql must already have been run
-- (public.profiles.membership_status is referenced by the 'approved' tier).
create extension if not exists "pgcrypto";

create table if not exists public.opportunities (
  id uuid primary key default gen_random_uuid(),

  title text not null check (char_length(title) between 3 and 200),
  slug text not null unique,
  -- Scholarship / Fellowship / Grant / Internship / Job / Mentorship / Programme
  type text not null,

  organization text,
  location text,
  summary text,
  description text, -- markdown
  application_url text,
  contact_email text,

  deadline date,
  amount_note text,

  -- 'public'   — anyone, including signed-out visitors
  -- 'members'  — any signed-in member
  -- 'approved' — only members whose profiles.membership_status = 'approved'
  visibility text not null default 'members'
    check (visibility in ('public', 'members', 'approved')),

  is_featured boolean not null default false,

  status text not null default 'draft'
    check (status in ('draft', 'published', 'closed', 'archived')),

  created_by uuid references public.profiles(id) on delete set null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists opportunities_status_deadline_idx
  on public.opportunities (status, deadline);

create index if not exists opportunities_visibility_status_idx
  on public.opportunities (visibility, status);

-- A member bookmarking a listing.
create table if not exists public.opportunity_saves (
  id uuid primary key default gen_random_uuid(),
  opportunity_id uuid not null references public.opportunities(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (opportunity_id, profile_id)
);

create index if not exists opportunity_saves_profile_idx
  on public.opportunity_saves (profile_id);

-- Mirrors public.touch_award_orders_updated_at() in 20260726_award_orders.sql.
create or replace function public.touch_opportunities_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists opportunities_set_updated_at on public.opportunities;
create trigger opportunities_set_updated_at
  before update on public.opportunities
  for each row execute function public.touch_opportunities_updated_at();

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
alter table public.opportunities enable row level security;
alter table public.opportunity_saves enable row level security;

-- Signed-out visitors: published + public only. This is the SQL twin of
-- visibleTiersFor(null) === ['public'].
drop policy if exists "Anon reads public opportunities" on public.opportunities;
create policy "Anon reads public opportunities" on public.opportunities
  for select to anon
  using (status = 'published' and visibility = 'public');

-- Signed-in members: published rows their tier allows. 'approved' rows require
-- an approved membership_status, matching visibleTiersFor({ status }).
--
-- profiles.membership_status is added by supabase/SETUP-MEMBER-HUB.sql, which
-- may not have been run on this database yet. Rather than fail the whole
-- migration on a missing column, fall back to a policy that grants only the
-- 'public'/'members' tiers — the least privileged reading, never the most.
drop policy if exists "Members read opportunities in their tier" on public.opportunities;
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'profiles' and column_name = 'membership_status'
  ) then
    execute $policy$
      create policy "Members read opportunities in their tier" on public.opportunities
        for select to authenticated
        using (
          status = 'published'
          and (
            visibility in ('public', 'members')
            or (
              visibility = 'approved'
              and exists (
                select 1 from public.profiles p
                where p.id = auth.uid() and p.membership_status = 'approved'
              )
            )
          )
        )
    $policy$;
  else
    raise notice 'public.profiles.membership_status is missing — creating the members-tier policy without the approved tier. Run supabase/SETUP-MEMBER-HUB.sql, then re-run this migration.';
    execute $policy$
      create policy "Members read opportunities in their tier" on public.opportunities
        for select to authenticated
        using (status = 'published' and visibility in ('public', 'members'))
    $policy$;
  end if;
end $$;

drop policy if exists "Admins manage opportunities" on public.opportunities;
create policy "Admins manage opportunities" on public.opportunities
  for all to authenticated
  using (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.role in ('admin', 'superadmin')
    )
  )
  with check (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.role in ('admin', 'superadmin')
    )
  );

drop policy if exists "Service role manages opportunities" on public.opportunities;
create policy "Service role manages opportunities" on public.opportunities
  for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');

-- A member may only ever see, create or remove their own bookmarks.
drop policy if exists "Members read their own saves" on public.opportunity_saves;
create policy "Members read their own saves" on public.opportunity_saves
  for select to authenticated using (auth.uid() = profile_id);

drop policy if exists "Members create their own saves" on public.opportunity_saves;
create policy "Members create their own saves" on public.opportunity_saves
  for insert to authenticated with check (auth.uid() = profile_id);

drop policy if exists "Members delete their own saves" on public.opportunity_saves;
create policy "Members delete their own saves" on public.opportunity_saves
  for delete to authenticated using (auth.uid() = profile_id);

drop policy if exists "Service role manages opportunity saves" on public.opportunity_saves;
create policy "Service role manages opportunity saves" on public.opportunity_saves
  for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');

comment on column public.opportunities.visibility is
  'public | members | approved — the tier a caller must reach to see this row. Enforced by visibleTiersFor() in lib/opportunities/server.ts.';

------------------------------------------------------------------------
-- END supabase/migrations/20260728_opportunities.sql
------------------------------------------------------------------------

------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260729_index_foreign_keys.sql
------------------------------------------------------------------------
-- 20260729_index_foreign_keys.sql
-- unindexed_foreign_keys: every FK below had no covering index, so each parent
-- delete forced a sequential scan of the child table to enforce the constraint,
-- and joins across the FK could not use an index. Idempotent.
--
-- Driven off pg_constraint rather than a hard-coded list, because three of the
-- affected tables (notification_history, support_tickets, support_messages)
-- exist in the live project but have no CREATE TABLE anywhere in this repo, so
-- naming them directly would break a fresh SETUP-ALL run.

do $$
declare fk record;
begin
  for fk in
    select c.conrelid, c.conrelid::regclass::text as tbl, c.conname,
      (select string_agg(quote_ident(a.attname), ', ' order by k.ord)
       from unnest(c.conkey) with ordinality k(attnum, ord)
       join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum) as cols
    from pg_constraint c
    join pg_class rel on rel.oid = c.conrelid
    join pg_namespace n on n.oid = rel.relnamespace
    where c.contype = 'f'
      and n.nspname = 'public'
      and not exists (
        select 1 from pg_index i
        where i.indrelid = c.conrelid
          and (i.indkey::int2[])[0:array_length(c.conkey, 1) - 1] = c.conkey
      )
  loop
    execute format(
      'create index if not exists %I on %s (%s)',
      'idx_' || fk.conname, fk.tbl, fk.cols
    );
  end loop;
end $$;

------------------------------------------------------------------------
-- END supabase/migrations/20260729_index_foreign_keys.sql
------------------------------------------------------------------------

------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260729_security_hardening.sql
------------------------------------------------------------------------
-- 20260729_security_hardening.sql
-- Remediates the Supabase database-linter security findings reported 2026-07-27.
-- Idempotent: safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. function_search_path_mutable
--    Pin search_path on every public function that lacks it, so a caller cannot
--    shadow `public` with a schema of their own and hijack an unqualified name.
-- ---------------------------------------------------------------------------
do $$
declare fn record;
begin
  for fn in
    select p.oid::regprocedure as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proconfig is null
  loop
    execute format('alter function %s set search_path = public', fn.sig);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 2. anon/authenticated_security_definer_function_executable
--    Trigger functions are granted EXECUTE to anon/authenticated by Supabase's
--    default grants, which publishes them at /rest/v1/rpc/<name>. They are only
--    ever meant to fire from triggers, so take the grant away.
--
--    NOTE: the RLS helper functions (is_site_admin, is_group_participant,
--    is_active_group_member, is_group_admin) deliberately keep their grants.
--    Postgres checks EXECUTE privilege when evaluating an RLS policy expression
--    as the querying role, so revoking them would turn every member_groups read
--    into "permission denied" instead of an empty result. They are SECURITY
--    DEFINER by necessity (to break RLS recursion) and now have a pinned
--    search_path; they return only a boolean.
-- ---------------------------------------------------------------------------
do $$
declare fn record;
begin
  for fn in
    select p.oid::regprocedure as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prorettype = 'trigger'::regtype
  loop
    execute format('revoke all on function %s from anon, authenticated', fn.sig);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 3. security_definer_view — public.awardee_directory
--    The view stays SECURITY DEFINER on purpose: it is the curated public
--    projection of awardees ⋈ profiles, and `profiles` intentionally has no
--    anon SELECT policy. What is fixed here is the payload — the view no longer
--    selects email, personal_email or phone, so the definer bypass cannot leak
--    contact details. lib/awardees.ts already hard-codes those three to null and
--    app/api/awardees/[id]/route.ts strips email, so no consumer loses data.
-- ---------------------------------------------------------------------------
--    CREATE OR REPLACE VIEW cannot remove columns, so this is a drop/recreate.
drop view if exists public.awardee_directory;

create view public.awardee_directory as
  select
    a.id as awardee_id,
    coalesce(p.id, a.profile_id) as profile_id,
    coalesce(p.slug, a.slug) as slug,
    coalesce(p.full_name, a.name) as name,
    coalesce(p.location, a.country) as country,
    p.location,
    coalesce(p.current_school, a.course) as current_school,
    coalesce(p.field_of_study, a.course) as field_of_study,
    coalesce(p.bio, a.bio) as bio,
    coalesce(p.avatar_url, a.avatar_url, a.image_url) as avatar_url,
    p.cover_image_url,
    coalesce(p.headline, a.headline) as headline,
    coalesce(p.tagline, a.tagline) as tagline,
    coalesce(p.achievements, a.achievements) as achievements,
    coalesce(p.gallery, a.gallery) as gallery,
    coalesce(p.video_links, a.video_links) as video_links,
    coalesce(p.social_links, a.social_links) as social_links,
    coalesce(p.interests, a.interests) as interests,
    p.cohort,
    p.metadata,
    coalesce(p.cgpa, a.cgpa) as cgpa,
    coalesce(p.year, a.year) as year,
    a.featured,
    a.created_at,
    coalesce(p.updated_at, a.updated_at) as updated_at,
    coalesce(p.is_public, a.is_public, true) as is_public,
    coalesce(p.role, 'user'::text) as role,
    coalesce(p.mentor, ''::text) as mentor,
    coalesce(p.impact_projects, a.impact_projects, 0) as impact_projects,
    coalesce(p.lives_impacted, a.lives_impacted, 0) as lives_impacted,
    coalesce(p.awards_received, a.awards_received, 0) as awards_received,
    coalesce(p.youtube_video_url, a.youtube_video_url) as youtube_video_url
  from public.awardees a
  left join public.profiles p on p.id = a.profile_id
  where coalesce(p.is_public, a.is_public, true);

grant select on public.awardee_directory to anon, authenticated;

comment on view public.awardee_directory is
  'Public awardee projection. SECURITY DEFINER by design so anon can read it without a profiles SELECT policy; contains no contact PII.';

-- ---------------------------------------------------------------------------
-- 4. public.awardees leaked every awardee email to anon
--    RLS is row-level only, so the "is_public = true" policy still exposed the
--    email column to GET /rest/v1/awardees?select=email. Column-level grants
--    close that. service_role is unaffected, and every route that legitimately
--    reads awardee emails (search, verify-email, export, signup) uses
--    createAdminClient().
-- ---------------------------------------------------------------------------
do $$
declare col record;
begin
  revoke select on public.awardees from anon, authenticated;
  for col in
    select column_name
    from information_schema.columns
    where table_schema = 'public' and table_name = 'awardees'
      and column_name <> 'email'
  loop
    execute format('grant select (%I) on public.awardees to anon, authenticated', col.column_name);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 5. rls_policy_always_true
--    Every write to these three tables goes through createAdminClient(), which
--    uses service_role and bypasses RLS. The permissive anon policies are pure
--    attack surface: anyone with the publishable key could forge contact-form
--    messages or delete other people's push subscriptions.
-- ---------------------------------------------------------------------------
--    Guarded on to_regclass: push_subscriptions and magazine_downloads exist in
--    the live project but have no CREATE TABLE in this repo, so a fresh
--    SETUP-ALL run would otherwise fail here.
do $$
declare t record;
begin
  for t in
    select * from (values
      ('push_subscriptions', 'Anyone can create subscription'),
      ('push_subscriptions', 'Anyone can delete own subscription'),
      ('messages',           'Anyone can submit messages'),
      ('magazine_downloads', 'Allow public inserts')
    ) as v(tbl, pol)
  loop
    if to_regclass('public.' || t.tbl) is not null then
      execute format('drop policy if exists %I on public.%I', t.pol, t.tbl);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 6. public_bucket_allows_listing
--    `awardees` and `uploads` are public buckets, so objects are served over
--    /storage/v1/object/public/... without touching RLS. These SELECT policies
--    only enable /storage/v1/object/list/..., i.e. anonymous enumeration of
--    every file. Nothing in the app calls .list(); images keep working.
-- ---------------------------------------------------------------------------
drop policy if exists "Public Access"           on storage.objects;
drop policy if exists "Allow public read access" on storage.objects;

-- ---------------------------------------------------------------------------
-- 7. multiple_permissive_policies on public.awardees
--    Two exact-duplicate pairs, left over from an earlier migration.
-- ---------------------------------------------------------------------------
drop policy if exists "Public visible awardees"    on public.awardees;
drop policy if exists "Service manages all awardees" on public.awardees;

------------------------------------------------------------------------
-- END supabase/migrations/20260729_security_hardening.sql
------------------------------------------------------------------------

------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260729_security_hardening_2.sql
------------------------------------------------------------------------
-- 20260729_security_hardening_2.sql
-- Second remediation pass: PUBLIC function grants, a broken posts UPDATE policy,
-- leftover duplicate policies, and the auth_rls_initplan performance lint.
-- Idempotent: safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. The first pass revoked EXECUTE from anon/authenticated, but Postgres also
--    grants EXECUTE to PUBLIC by default (`=X/postgres` in proacl), which is
--    what actually kept every function reachable at /rest/v1/rpc/<name>.
--    Revoke from PUBLIC, then grant back only the RLS helpers that policies
--    genuinely need — policy expressions are evaluated with the querying role's
--    privileges, so without these grants member_groups reads would fail with
--    "permission denied" instead of returning an empty set.
--    No application code calls supabase.rpc() against this schema.
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public;

do $$
declare f record;
begin
  for f in
    select * from (values
      ('public.is_site_admin(uuid)',                'anon, authenticated'),
      ('public.is_group_participant(uuid, uuid)',   'anon, authenticated'),
      ('public.is_active_group_member(uuid, uuid)', 'anon, authenticated'),
      ('public.is_group_admin(uuid, uuid)',         'anon, authenticated'),
      ('public.is_post_owner(uuid)',                'authenticated')
    ) as v(sig, roles)
  loop
    if to_regprocedure(f.sig) is not null then
      execute format('grant execute on function %s to %s', f.sig, f.roles);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 2. posts_update_owner was created with USING (true) WITH CHECK (true) while
--    its three sibling policies all use is_post_owner(author_id). Any signed-in
--    user could edit or reassign any post. Restore the owner check.
-- ---------------------------------------------------------------------------
--    `posts` exists in the live project but has no CREATE TABLE in this repo,
--    so this is guarded for a fresh SETUP-ALL run.
do $$
begin
  if to_regclass('public.posts') is not null and to_regprocedure('public.is_post_owner(uuid)') is not null then
    drop policy if exists posts_update_owner on public.posts;
    create policy posts_update_owner on public.posts
      for update to authenticated
      using (is_post_owner(author_id))
      with check (is_post_owner(author_id));

    -- exact-duplicate permissive policies on the same table
    drop policy if exists "Public published posts"         on public.posts;
    drop policy if exists "Service role manages all posts"  on public.posts;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 3. feature_requests accepted unauthenticated inserts. Every read and write in
--    app/api/feature-requests/route.ts uses createAdminClient(), so the anon
--    policy is unused attack surface.
-- ---------------------------------------------------------------------------
drop policy if exists "Anyone can submit feature_requests" on public.feature_requests;

-- ---------------------------------------------------------------------------
-- 4. awardees is read-only for anon/authenticated; all writes use service_role.
--    RLS already blocked these, but the grants had no reason to exist.
-- ---------------------------------------------------------------------------
revoke insert, update, delete, references on public.awardees from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. auth_rls_initplan — wrap auth.uid() / auth.role() / auth.jwt() in a scalar
--    subquery so the planner evaluates them once per statement instead of once
--    per row. Rewrites each affected policy in place, preserving name, command,
--    roles and permissive/restrictive kind.
-- ---------------------------------------------------------------------------
do $$
declare
  p record;
  new_qual text;
  new_check text;
  cmd text;
  ddl text;
begin
  for p in
    select c.relname as tbl, pol.polname, pol.polcmd, pol.polpermissive,
      coalesce(
        (select string_agg(quote_ident(r.rolname), ', ') from pg_roles r where r.oid = any(pol.polroles)),
        'public') as roles,
      pg_get_expr(pol.polqual, pol.polrelid) as qual,
      pg_get_expr(pol.polwithcheck, pol.polrelid) as wc
    from pg_policy pol
    join pg_class c on c.oid = pol.polrelid
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
  loop
    new_qual  := regexp_replace(p.qual, '(?<!SELECT )auth\.(uid|role|jwt)\(\)', '(select auth.\1())', 'g');
    new_check := regexp_replace(p.wc,   '(?<!SELECT )auth\.(uid|role|jwt)\(\)', '(select auth.\1())', 'g');

    continue when new_qual is not distinct from p.qual
             and new_check is not distinct from p.wc;

    cmd := case p.polcmd
             when 'r' then 'select' when 'a' then 'insert'
             when 'w' then 'update' when 'd' then 'delete'
             else 'all' end;

    ddl := format('create policy %I on public.%I as %s for %s to %s',
                  p.polname, p.tbl,
                  case when p.polpermissive then 'permissive' else 'restrictive' end,
                  cmd, p.roles);

    if new_qual is not null then
      ddl := ddl || format(' using (%s)', new_qual);
    end if;
    if new_check is not null then
      ddl := ddl || format(' with check (%s)', new_check);
    end if;

    execute format('drop policy %I on public.%I', p.polname, p.tbl);
    execute ddl;
  end loop;
end $$;

------------------------------------------------------------------------
-- END supabase/migrations/20260729_security_hardening_2.sql
------------------------------------------------------------------------

------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260816_create_distributed_rate_limits.sql
------------------------------------------------------------------------
-- Shared, atomic API rate limiting for serverless/multi-instance deployments.
-- Identifiers are SHA-256 hashed in the application before reaching this table.

create table if not exists public.api_rate_limits (
  key_hash text primary key,
  request_count integer not null check (request_count >= 0),
  reset_at timestamptz not null,
  updated_at timestamptz not null default now()
);

create index if not exists api_rate_limits_reset_at_idx
  on public.api_rate_limits (reset_at);

alter table public.api_rate_limits enable row level security;

revoke all on table public.api_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on table public.api_rate_limits to service_role;

create or replace function public.consume_api_rate_limit(
  p_key_hash text,
  p_limit integer,
  p_window_seconds integer
)
returns table (
  allowed boolean,
  request_count integer,
  remaining integer,
  reset_at timestamptz
)
language plpgsql
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_count integer;
  v_reset_at timestamptz;
begin
  if p_key_hash is null or length(p_key_hash) <> 64 then
    raise exception 'Invalid rate-limit key hash';
  end if;

  if p_limit <= 0 or p_window_seconds <= 0 then
    raise exception 'Rate-limit values must be positive';
  end if;

  -- Bound inputs so a caller cannot accidentally create pathological windows.
  if p_limit > 100000 or p_window_seconds > 86400 then
    raise exception 'Rate-limit values exceed allowed bounds';
  end if;

  insert into public.api_rate_limits as limits (
    key_hash,
    request_count,
    reset_at,
    updated_at
  )
  values (
    p_key_hash,
    1,
    v_now + make_interval(secs => p_window_seconds),
    v_now
  )
  on conflict (key_hash) do update
    set request_count = case
          when limits.reset_at <= v_now then 1
          else limits.request_count + 1
        end,
        reset_at = case
          when limits.reset_at <= v_now then v_now + make_interval(secs => p_window_seconds)
          else limits.reset_at
        end,
        updated_at = v_now
  returning limits.request_count, limits.reset_at
  into v_count, v_reset_at;

  -- Opportunistic bounded-state cleanup. The reset_at index keeps this cheap.
  delete from public.api_rate_limits as stale
  where stale.reset_at < v_now - interval '1 day';

  return query
  select
    v_count <= p_limit,
    v_count,
    greatest(p_limit - v_count, 0),
    v_reset_at;
end;
$$;

revoke all on function public.consume_api_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.consume_api_rate_limit(text, integer, integer) to service_role;

comment on table public.api_rate_limits is
  'Server-side shared API rate-limit counters. key_hash values are SHA-256 digests, never raw client identifiers.';
comment on function public.consume_api_rate_limit(text, integer, integer) is
  'Atomically consumes one request from a fixed-window shared rate limit and returns remaining quota.';

------------------------------------------------------------------------
-- END supabase/migrations/20260816_create_distributed_rate_limits.sql
------------------------------------------------------------------------

------------------------------------------------------------------------
-- BEGIN supabase/migrations/20260904_portfolio_covers.sql
------------------------------------------------------------------------
alter table public.profiles add column if not exists portfolio_cover_url text;

create table if not exists public.portfolio_cover_generations (
  id uuid primary key default gen_random_uuid(),
  member_id uuid not null references public.profiles(id) on delete cascade,
  status text not null default 'queued' check (status in ('queued','processing','ready','selected','failed','rejected','expired')),
  tailoring text not null check (tailoring in ('male','female')),
  fields jsonb not null default '{}'::jsonb,
  consent_version text not null default 'portfolio-cover-v1',
  consented_at timestamptz not null default now(),
  source_path text,
  option_paths jsonb not null default '{}'::jsonb,
  selected_variant text check (selected_variant in ('executive-charcoal','leadership-ivory')),
  selected_url text,
  provider_request_ids jsonb not null default '[]'::jsonb,
  attempt integer not null default 1 check (attempt between 1 and 2),
  failure_code text,
  failure_message text,
  expires_at timestamptz not null default (now() + interval '7 days'),
  reset_by uuid references auth.users(id) on delete set null,
  reset_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists portfolio_cover_generations_member_idx on public.portfolio_cover_generations(member_id, created_at desc);
create unique index if not exists portfolio_cover_one_active_idx on public.portfolio_cover_generations(member_id)
  where status in ('queued','processing');

alter table public.portfolio_cover_generations enable row level security;
drop policy if exists portfolio_cover_member_read on public.portfolio_cover_generations;
create policy portfolio_cover_member_read on public.portfolio_cover_generations
  for select using (auth.uid() = member_id);

insert into storage.buckets (id, name, public) values
  (coalesce(nullif(current_setting('app.portfolio_source_bucket', true), ''), 'portfolio-sources'), coalesce(nullif(current_setting('app.portfolio_source_bucket', true), ''), 'portfolio-sources'), false),
  (coalesce(nullif(current_setting('app.portfolio_option_bucket', true), ''), 'portfolio-options'), coalesce(nullif(current_setting('app.portfolio_option_bucket', true), ''), 'portfolio-options'), false),
  (coalesce(nullif(current_setting('app.portfolio_cover_bucket', true), ''), 'portfolio-covers'), coalesce(nullif(current_setting('app.portfolio_cover_bucket', true), ''), 'portfolio-covers'), true)
on conflict (id) do nothing;

create or replace function public.set_portfolio_cover_updated_at() returns trigger
language plpgsql security invoker set search_path = public as $$
begin new.updated_at = now(); return new; end; $$;

drop trigger if exists portfolio_cover_updated_at on public.portfolio_cover_generations;
create trigger portfolio_cover_updated_at before update on public.portfolio_cover_generations
for each row execute function public.set_portfolio_cover_updated_at();

-- Keep the public BIO directory aware of the selected cover without exposing
-- any private source or option objects.
drop view if exists public.awardee_directory;
create view public.awardee_directory as
  select
    a.id as awardee_id,
    coalesce(p.id, a.profile_id) as profile_id,
    coalesce(p.slug, a.slug) as slug,
    coalesce(p.full_name, a.name) as name,
    coalesce(p.location, a.country) as country,
    p.location,
    coalesce(p.current_school, a.course) as current_school,
    coalesce(p.field_of_study, a.course) as field_of_study,
    coalesce(p.bio, a.bio) as bio,
    coalesce(p.avatar_url, a.avatar_url, a.image_url) as avatar_url,
    p.cover_image_url,
    p.portfolio_cover_url,
    coalesce(p.headline, a.headline) as headline,
    coalesce(p.tagline, a.tagline) as tagline,
    coalesce(p.achievements, a.achievements) as achievements,
    coalesce(p.gallery, a.gallery) as gallery,
    coalesce(p.video_links, a.video_links) as video_links,
    coalesce(p.social_links, a.social_links) as social_links,
    coalesce(p.interests, a.interests) as interests,
    p.cohort,
    p.metadata,
    coalesce(p.cgpa, a.cgpa) as cgpa,
    coalesce(p.year, a.year) as year,
    a.featured,
    a.created_at,
    coalesce(p.updated_at, a.updated_at) as updated_at,
    coalesce(p.is_public, a.is_public, true) as is_public,
    coalesce(p.role, 'user'::text) as role,
    coalesce(p.mentor, ''::text) as mentor,
    coalesce(p.impact_projects, a.impact_projects, 0) as impact_projects,
    coalesce(p.lives_impacted, a.lives_impacted, 0) as lives_impacted,
    coalesce(p.awards_received, a.awards_received, 0) as awards_received,
    coalesce(p.youtube_video_url, a.youtube_video_url) as youtube_video_url
  from public.awardees a
  left join public.profiles p on p.id = a.profile_id
  where coalesce(p.is_public, a.is_public, true);
grant select on public.awardee_directory to anon, authenticated;

------------------------------------------------------------------------
-- END supabase/migrations/20260904_portfolio_covers.sql
